const g = $('Get Settings').first().json;
return [{ json: mkLog({ event_type: 'CAMPAIGN_OFF_SKIP', campaign_id: s(g.settings.campaign_id), status: 'SKIPPED',
  metadata: g.problems && g.problems.length ? 'Settings problems: ' + g.problems.join(', ') : 'campaign_enabled is not ON' }) }];

const TZ = 'Africa/Lagos';
const s = (v) => String(v === null || v === undefined ? '' : v).trim();
const todayStr = () => new Intl.DateTimeFormat('en-CA', { timeZone: TZ }).format(new Date());
const nowIso = () => new Date(Date.now() + 3600000).toISOString().replace(/\.\d{3}Z$/, '+01:00');
const uid = (p) => p + '-' + Date.now().toString(36).toUpperCase() + '-' + Math.random().toString(36).slice(2, 7).toUpperCase();
const isEmail = (e) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s(e));
const isDate = (d) => /^\d{4}-\d{2}-\d{2}$/.test(d) && !isNaN(Date.parse(d + 'T00:00:00Z'));
const daysBetween = (a, b) => Math.floor((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / 86400000);
const mkLog = (o) => Object.assign({ event_id: uid('EVT'), customer_id: '', email: '', event_type: '', campaign_id: '', email_sequence: '', message_id: '', booking_id: '', timestamp: nowIso(), status: '', error: '', metadata: '' }, o);
const mkErr = (o) => Object.assign({ error_id: uid('ERR'), workflow: '', customer_id: '', node: '', error_type: 'UNKNOWN', message: '', timestamp: nowIso(), retry_count: 0, resolved: 'FALSE', execution_id: String($execution.id) }, o);

const S = $('Get Settings').first().json.settings;
const rows = $input.all().map(i => i.json).filter(r => s(r.customer_id) || s(r.email));
const today = todayStr();
const idCount = {};
rows.forEach(r => { const id = s(r.customer_id); if (id) idCount[id] = (idCount[id] || 0) + 1; });
const out = [];
for (const r of rows) {
  const id = s(r.customer_id);
  if (!id || idCount[id] !== 1) continue;
  if (!isEmail(r.email)) continue;
  if (s(r.consent_status) !== 'OPTED_IN') continue;
  if (s(r.booking_status) === 'BOOKED') continue;
  if (!['CONTACTED', 'FOLLOW_UP_PENDING'].includes(s(r.campaign_status))) continue;
  const count = Number(r.follow_up_count) || 0;
  if (count >= S.max_followups) continue;
  const lc = s(r.last_contacted_at).slice(0, 10);
  if (!isDate(lc)) continue;
  if (daysBetween(lc, today) < S.days_between_followups) continue;
  out.push({ customer_id: id, email_sequence: 'FOLLOWUP-' + (count + 1), _sort: lc });
}
out.sort((a, b) => (a._sort < b._sort ? -1 : 1));
const cap = Math.max(0, Number(S.max_emails_per_run) || 0);
return out.slice(0, cap).map(o => ({ json: { customer_id: o.customer_id, email_sequence: o.email_sequence } }));
